class ChatbotInterface {
    constructor(botElementId) {
        //this.botElement = document.getElementById(botElementId)
        this.botElement = document.getElementsByTagName("bsc-chat")[0];
    }

    setApiKey(apiKey) {
        this.botElement.setAttribute('execute', '{"command":"setChatKey", "args":{"chatKey":"' + apiKey + '"}}')
    }

    sendSilentMessage(message) {
        this.botElement.setAttribute('execute', '{"command":"sendSilentMessage", "args":{"intents":"' + message + '"}}')
    }

    maximize() {
        this.botElement.setAttribute('execute', '{"command":"maximize"}')
    }

    minimize() {
        this.botElement.setAttribute('execute', '{"command":"minimize"}')
    }

    customEvent(name, callback) {
        this.botElement.addEventListener(name,
            callback
        );
    }
}